mapper.select:
SELECT count(distinct(dataTable.device_code)) as deviceCountTotal, count(distinct case when dataTable.device_status = 0 then dataTable.device_code end) as devCountOnline, count(distinct case when dataTable.device_status = 1 then dataTable.device_code end) as devCountOffline, count((c.channel_code)) as channelCountTotal, count( case when c.channel_status = 0 then c.channel_code end) as channelCountOnline, count( case when c.channel_status = 1 then c.channel_code end) as channelCountOffline FROM vm_device_info_t dataTable left join vm_channel_info_t c on dataTable.device_code = c.device_code and c.delete_flag = '0'
left JOIN vm_order_devices od ON od.device_code = dataTable.device_code
left join vm_tower_device_labels_rel lab on lab.device_code = dataTable.device_code
and od.tenant_id = #{tenantId} and od.delete_flag = '0' and od.ord_status IN (0, 1, 2)
and lab.label_id = #{labelId}
and lab.label_id in
#{item}
and ( dataTable.province_id in
#{item}
or dataTable.city_id in
#{item}
or dataTable.county_id in
#{item}
or dataTable.town_code in
#{item}
)
and dataTable.delete_flag = '0'
AND dataTable.device_code in
#{deviceCode}

SELECT COUNT( IF ( a.STATUS = 0, 1, NULL )) AS iotDeviceOnlineCount, COUNT( IF ( a.STATUS = 1, 1, NULL )) AS iotDeviceOfflineCount, COUNT( a.STATUS ) AS iotDeviceCount FROM ( SELECT DISTINCT m.device_code, m.device_status as STATUS FROM vm_iot_device_t m inner JOIN ( SELECT DISTINCT device_code FROM vm_order_sensor_devices WHERE ord_status IN ( '0', '1', '2' ) AND delete_flag = 0 ) t2 ON m.device_code = t2.device_code where m.delete_flag = '0' and m.category_code = 2
AND m.device_code in
#{deviceCode}
) a

SELECT COUNT( IF ( a.STATUS = 0, 1, NULL )) AS hornDeviceOfflineCount, COUNT( IF ( a.STATUS = 1, 1, NULL )) AS hornDeviceFreeCount, COUNT( IF ( a.STATUS = 2, 1, NULL )) AS hornDeviceWorkCount, COUNT( IF ( a.STATUS = 3, 1, NULL )) AS hornDeviceFailCount, COUNT( IF ( a.STATUS = 4, 1, NULL )) AS hornDeviceNoConnectCount, COUNT( IF ( a.STATUS = 1 OR a.STATUS = 2 OR a.STATUS = 3, 1, NULL )) AS hornDeviceOnlineCount, COUNT( a.deviceCode ) AS hornDeviceCount from ( SELECT distinct m.device_code deviceCode, m.device_status STATUS from vm_horn_device_info_t m
inner JOIN ( SELECT DISTINCT device_code FROM vm_order_horn_devices WHERE ord_status IN ( '0', '1', '2' ) AND delete_flag = 0 ) t2 ON m.device_code = t2.device_code
where m.delete_flag = 0
and m.device_type = #{param.deviceType}
and ( m.province_code in
#{item}
or m.city_code in
#{item}
or m.county_code in
#{item}
or m.town_code in
#{item}
)
AND m.device_code in
#{deviceCode}
) a
where exists(select od.id from vm_order_horn_devices od join sys_tenant_info ti on od.tenant_id = ti.tenant_id where od.device_code = a.deviceCode and od.delete_flag ='0' and ti.del_flag = '0' and od.tenant_id = #{param.tenantId} )

SELECT COUNT( IF ( a.STATUS = 0, 1, NULL )) AS radarDeviceOnlineCount, COUNT( IF ( a.STATUS = 1, 1, NULL )) AS radarDeviceOfflineCount, COUNT( a.STATUS ) AS radarDeviceCount FROM ( SELECT DISTINCT m.device_code, m.device_status as STATUS FROM vm_iot_device_t m inner JOIN ( SELECT DISTINCT device_code FROM vm_order_sensor_devices WHERE ord_status IN ( '0', '1', '2' ) AND delete_flag = 0 ) t2 ON m.device_code = t2.device_code where m.category_code = 1 and m.delete_flag = '0'
AND m.device_code in
#{deviceCode}
) a
